      /// Name of the removed canvas
      public let canvasName: String

      /// UUID of the removed canvas
      public let canvasUuid: UUID

      public init(canvasName: String, canvasUuid: UUID) {
        self.canvasName = canvasName
        self.canvasUuid = canvasUuid
      }
    }

    /// The name of a canvas has changed.
    /// > Event Subscription: ``OBSWS/Enums/EventSusbcription/canvases``
    /// > Category: `Canvases`
    /// > Complexity: `2/5`
    /// > Version: Latest Supported RPC Version - `1`
    /// > Since: Added in v5.7.0
    public struct CanvasNameChanged: OBSEvent {
      /// UUID of the canvas
      public let canvasUuid: UUID

      /// Old name of the canvas
      public let oldCanvasName: String

      /// New name of the canvas
      public let canvasName: String

      public init(canvasUuid: UUID, oldCanvasName: String, canvasName: String) {
        self.canvasUuid = canvasUuid
        self.oldCanvasName = oldCanvasName
        self.canvasName = canvasName
      }
    }

    /// The current scene collection has begun changing.
    /// 
    /// > Note: We recommend using this event to trigger a pause of all polling requests, as performing any requests during a
    /// scene collection change is considered undefined behavior and can cause crashes!
    /// > Event Subscription: ``OBSWS/Enums/EventSusbcription/config``
    /// > Category: `Config`
    /// > Complexity: `1/5`
    /// > Version: Latest Supported RPC Version - `1`
    /// > Since: Added in v5.0.0
    public struct CurrentSceneCollectionChanging: OBSEvent {
      /// Name of the current scene collection
      public let sceneCollectionName: String

      public init(sceneCollectionName: String) {
        self.sceneCollectionName = sceneCollectionName
      }
    }

    /// The current scene collection has changed.
    /// 
    /// > Note: If polling has been paused during `CurrentSceneCollectionChanging`, this is the que to restart polling.
    /// > Event Subscription: ``OBSWS/Enums/EventSusbcription/config``
    /// > Category: `Config`
    /// > Complexity: `1/5`
    /// > Version: Latest Supported RPC Version - `1`
    /// > Since: Added in v5.0.0
    public struct CurrentSceneCollectionChanged: OBSEvent {
      /// Name of the new scene collection
      public let sceneCollectionName: String

      public init(sceneCollectionName: String) {
        self.sceneCollectionName = sceneCollectionName
      }
    }

    /// The scene collection list has changed.
    /// > Event Subscription: ``OBSWS/Enums/EventSusbcription/config``
    /// > Category: `Config`
    /// > Complexity: `1/5`
    /// > Version: Latest Supported RPC Version - `1`
    /// > Since: Added in v5.0.0
    public struct SceneCollectionListChanged: OBSEvent {
      /// Updated list of scene collections
      public let sceneCollections: [String]

      public init(sceneCollections: [String]) {
        self.sceneCollections = sceneCollections
      }
    }

    /// The current profile has begun changing.
    /// > Event Subscription: ``OBSWS/Enums/EventSusbcription/config``
    /// > Category: `Config`
    /// > Complexity: `1/5`
    /// > Version: Latest Supported RPC Version - `1`
    /// > Since: Added in v5.0.0
    public struct CurrentProfileChanging: OBSEvent {
      /// Name of the current profile
      public let profileName: String

      public init(profileName: String) {
        self.profileName = profileName
      }
    }

    /// The current profile has changed.
    /// > Event Subscription: ``OBSWS/Enums/EventSusbcription/config``
    /// > Category: `Config`
    /// > Complexity: `1/5`
    /// > Version: Latest Supported RPC Version - `1`
    /// > Since: Added in v5.0.0
    public struct CurrentProfileChanged: OBSEvent {
      /// Name of the new profile
      public let profileName: String

      public init(profileName: String) {
        self.profileName = profileName
      }
    }

    /// The profile list has changed.
    /// > Event Subscription: ``OBSWS/Enums/EventSusbcription/config``
    /// > Category: `Config`
    /// > Complexity: `1/5`
    /// > Version: Latest Supported RPC Version - `1`
    /// > Since: Added in v5.0.0
    public struct ProfileListChanged: OBSEvent {
      /// Updated list of profiles
      public let profiles: [String]

      public init(profiles: [String]) {
        self.profiles = profiles
      }
    }

    /// A source's filter list has been reindexed.
    /// > Event Subscription: ``OBSWS/Enums/EventSusbcription/filters``
    /// > Category: `Filters`
